function BellIcon(){return <span aria-hidden>◉</span>}
function TechCanvas(){
  const ref=useRef<HTMLCanvasElement>(null);
  useEffect(()=>{
    const canvas=ref.current;if(!canvas)return;
    const ctx=canvas.getContext("2d");if(!ctx)return;
    let frame=0;let particles:Array<{x:number;y:number;vx:number;vy:number;r:number;a:number}>=[];
    const resize=()=>{
      const box=canvas.getBoundingClientRect();const dpr=Math.min(window.devicePixelRatio||1,2);
      canvas.width=Math.max(1,Math.floor(box.width*dpr));canvas.height=Math.max(1,Math.floor(box.height*dpr));
      ctx.setTransform(dpr,0,0,dpr,0,0);
      const count=Math.min(70,Math.max(28,Math.floor(box.width/13)));
      particles=Array.from({length:count},()=>({x:Math.random()*box.width,y:Math.random()*box.height,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,r:.6+Math.random()*1.7,a:.25+Math.random()*.6}));
    };
    const draw=()=>{
      const box=canvas.getBoundingClientRect();ctx.clearRect(0,0,box.width,box.height);
      const g=ctx.createRadialGradient(box.width*.5,box.height*.48,12,box.width*.5,box.height*.48,Math.max(box.width,box.height)*.48);
      g.addColorStop(0,"rgba(255,106,0,.15)");g.addColorStop(.42,"rgba(255,106,0,.04)");g.addColorStop(1,"rgba(0,0,0,0)");
      ctx.fillStyle=g;ctx.fillRect(0,0,box.width,box.height);
      particles.forEach((p,i)=>{
        p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>box.width)p.vx*=-1;if(p.y<0||p.y>box.height)p.vy*=-1;
        ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=`rgba(255,154,82,${p.a})`;ctx.fill();
        for(let j=i+1;j<particles.length;j++){const q=particles[j],dx=p.x-q.x,dy=p.y-q.y,d=Math.hypot(dx,dy);if(d<95){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=`rgba(255,106,0,${.08*(1-d/95)})`;ctx.lineWidth=.7;ctx.stroke();}}
      });
      const t=performance.now()/1800;const cx=box.width*.5+Math.cos(t)*18,cy=box.height*.5+Math.sin(t*1.2)*12;
      ctx.beginPath();ctx.arc(cx,cy,82+Math.sin(t*2)*7,0,Math.PI*2);ctx.strokeStyle="rgba(255,106,0,.18)";ctx.lineWidth=1.2;ctx.stroke();
      frame=requestAnimationFrame(draw);
    };
    resize();window.addEventListener("resize",resize);draw();
    return()=>{cancelAnimationFrame(frame);window.removeEventListener("resize",resize)};
  },[]);
  return <canvas ref={ref} className="absolute inset-0 h-full w-full" aria-hidden="true"/>;
}
