function LiveTrending({compact=false}:{compact?:boolean}){
  const[topic,setTopic]=useState("all");
  const[items,setItems]=useState<any[]>([]);
  const[loading,setLoading]=useState(true);
  const[error,setError]=useState("");
  const topics=["all","AI","Cybersecurity","Software","Hardware","Robotics","Africa Tech","Space Tech"];

  useEffect(()=>{
    let active=true;
    setLoading(true);
    setError("");
    api.trending(topic,compact?12:60,false)
      .then(data=>{if(active)setItems(data.items||[])})
      .catch(err=>{if(active){setItems([]);setError(err instanceof Error?err.message:"Live feeds unavailable")}})
      .finally(()=>{if(active)setLoading(false)});
    return()=>{active=false};
  },[topic,compact]);

  let body:React.ReactNode=null;
  if(loading){
    body=<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{Array.from({length:compact?6:9},(_,i)=><div key={i} className="glass-card h-44 animate-pulse"/>)}</div>;
  }else if(error){
    body=<div className="glass-card p-7 text-sm text-zinc-400">{error}</div>;
  }else if(!items.length){
    body=<div className="glass-card p-7 text-sm text-zinc-400">No live stories are available for this topic right now.</div>;
  }else{
    body=<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map(item=>{
      const openSource=()=>window.open(item.url,"_blank","noopener,noreferrer");
      return <div key={item.id} role="link" tabIndex={0} onClick={openSource} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openSource()}}} className="glass-card group cursor-pointer overflow-hidden focus:outline-none focus:ring-2 focus:ring-orange/50">
        <div className="h-40 overflow-hidden bg-black/30">
          {item.image?<img src={item.image} alt="" className="h-full w-full object-cover transition duration-700 group-hover:scale-105"/>:<div className="grid h-full place-items-center text-orange/50"><Bot size={34}/></div>}
        </div>
        <div className="p-5">
          <div className="flex flex-wrap gap-2 font-mono text-[9px] uppercase tracking-[.15em]">
            <span className="text-orange">{item.topic}</span>
            <span className="text-zinc-600">· {item.source}</span>
          </div>
          <h3 className="mt-2 font-display text-xl font-semibold leading-snug group-hover:text-orange">{item.title}</h3>
          <p className="mt-2 line-clamp-3 text-sm leading-6 text-zinc-500">{item.summary}</p>
          <div className="mt-4 flex items-center justify-between text-[10px] text-zinc-600">
            <span>{new Date(item.publishedAt).toLocaleString()}</span>
            <span className="text-orange">Read source ↗</span>
          </div>
        </div>
      </div>
    })}</div>;
  }

  return <section className={compact?"":"mx-auto max-w-[1440px] px-5 py-20 lg:px-10"}>
    <div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
      <div>
        <div className="mb-2 font-mono text-[10px] uppercase tracking-[.25em] text-orange">Live / multi-source</div>
        <h2 className="font-display text-4xl font-bold md:text-5xl">{compact?"Trending now":"Global technology signal"}</h2>
        <p className="mt-2 max-w-2xl text-sm leading-6 text-zinc-500">Google News searches plus selected publisher and official technology RSS feeds, deduplicated and ranked by publication time.</p>
      </div>
    </div>
    <div className="mb-6 flex flex-wrap gap-2">{topics.map(x=><button key={x} onClick={()=>setTopic(x)} className={topic===x?"liquid-button":"liquid-button ghost"}>{x==="all"?"All":x}</button>)}</div>
    {body}
  </section>;
}
function EditorialStories(){const[items,setItems]=useState<any[]>([]);const[loading,setLoading]=useState(true);useEffect(()=>{api.articles().then(setItems).catch(()=>setItems([])).finally(()=>setLoading(false))},[]);if(loading)return <Section title="From the NextBit Desk" kicker="Original editorial"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{Array.from({length:3}).map((_,i)=><div key={i} className="glass-card h-56 animate-pulse"/>)}</div></Section>;if(!items.length)return <Section title="From the NextBit Desk" kicker="Original editorial"><div className="glass-card p-7 text-sm text-zinc-500">No published editorial stories yet.</div></Section>;return <Section title="From the NextBit Desk" kicker="Admin-published / original NextBit" action={()=>go("news")}><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{items.slice(0,6).map(a=><button key={a.id} onClick={()=>go("article",a.id)} className="glass-card group overflow-hidden text-left"><div className="h-52 overflow-hidden bg-black/30">{a.image_url?<img src={a.image_url} alt="" className="h-full w-full object-cover transition duration-700 group-hover:scale-105"/>:<div className="grid h-full place-items-center font-display text-4xl text-orange/40">NB</div>}</div><div className="p-5"><div className="flex flex-wrap gap-2 font-mono text-[9px] uppercase tracking-[.15em]"><span className="text-orange">{a.category}</span><span className="text-zinc-600">· NextBit Desk</span></div><h3 className="mt-3 font-display text-2xl font-semibold group-hover:text-orange">{a.title}</h3><p className="mt-2 line-clamp-3 text-sm leading-6 text-zinc-500">{a.summary}</p><div className="mt-5 text-xs text-orange">Read on NextBit <ArrowRight className="ml-1 inline" size={13}/></div></div></button>)}</div></Section>}

function Home({saved,toggle}:{saved:Set<string>;toggle:(x:string)=>void}){return <><EditorialStories/><LiveTrending/><Section title="The global ICT map" kicker="Roadmaps" action={()=>go("roadmaps")}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{["Software Engineering","AI & Machine Learning","Cybersecurity","Electronics Engineering","Computer Networking","Semiconductors & VLSI"].map(x=>{const r=ROADMAPS.find(v=>v.title===x)!;return <button key={x} onClick={()=>go("roadmap",r.id)} className="glass-card p-6 text-left"><div className="font-mono text-[9px] uppercase tracking-[.2em] text-orange">{r.group}</div><h3 className="mt-3 font-display text-2xl font-semibold">{r.title}</h3><p className="mt-2 text-sm leading-6 text-zinc-500">{r.desc}</p><div className="mt-5 text-xs text-zinc-500">{r.steps.length} stages <ArrowRight className="ml-1 inline text-orange" size={13}/></div></button>})}</div></Section><Section title="Inside the signal" kicker="Editorial analysis"><div className="grid gap-6 lg:grid-cols-2"><div className="glass-card grid min-h-80 place-items-center grid-bg"><div className="float size-36 rotate-45 border-2 border-orange bg-orange/5 shadow-[0_0_80px_rgba(255,106,0,.2)]"/></div><div className="glass-card p-7"><div className="font-mono text-[10px] text-orange">WHY IT MATTERS</div><h3 className="mt-6 font-display text-3xl font-bold">Technology stories should connect the dots.</h3><p className="mt-4 leading-8 text-zinc-400">NextBit puts the event, technical context, infrastructure impact and industry consequence into one editorial view.</p><div className="mt-6 grid gap-2 sm:grid-cols-3">{["What changed?","Why it matters","Industry impact"].map(x=><div key={x} className="border border-line p-3 text-xs text-zinc-400">{x}</div>)}</div></div></div></Section><Section title="Ask NextBit AI" kicker="Intelligence layer"><div className="glass-card border-orange/20 bg-orange/5 p-8"><div className="grid gap-8 lg:grid-cols-[1fr_.9fr]"><div><div className="flex gap-2 text-orange"><Bot/>NextBit AI</div><h3 className="mt-4 font-display text-4xl font-bold">Analyze the technology behind the headline.</h3><p className="mt-3 text-zinc-400">Compare technologies, map systems, summarize signals and surface technical context.</p><LiquidButton onClick={()=>go("search")}>Open AI workspace <ArrowRight className="ml-2 inline" size={15}/></LiquidButton></div><div className="grid gap-2">{["Compare GPUs for AI workloads.","Summarize 5G's effect on Africa.","Map the attack surface of a cloud app.","Trace the semiconductor supply chain."].map(q=><button key={q} onClick={()=>go("search")} className="glass p-4 text-left text-sm text-zinc-400 hover:text-white">{q}<ArrowRight className="float-right" size={14}/></button>)}</div></div></div></Section><Section title="From code to circuits" kicker="Technology domains"><div className="grid gap-4 md:grid-cols-3">{[["Software Engineering",Code2],["Electronics",Zap],["Cybersecurity",ShieldCheck]].map(([n,I]:any)=><button key={n} onClick={()=>go("roadmap",ROADMAPS.find(r=>r.title===n)?.id||"software-engineering")} className="glass-card p-7 text-left"><I className="text-orange"/><h3 className="mt-14 font-display text-2xl font-semibold">{n}</h3><p className="mt-2 text-sm text-zinc-500">See the ecosystem, stages and production technology map.</p></button>)}</div></Section><Section title="Build something real" kicker="Hands-on projects" action={()=>go("project")}><div className="grid gap-5 md:grid-cols-3">{P.map(p=><button onClick={()=>go("project",p.id)} key={p.id} className="glass-card group overflow-hidden text-left"><img src={p.img} className="h-44 w-full object-cover transition duration-700 group-hover:scale-105" alt=""/><div className="p-5"><div className="font-mono text-[10px] text-orange">{p.tech} · {p.level}</div><h3 className="mt-2 font-display text-xl font-semibold">{p.title}</h3><p className="mt-2 text-xs text-zinc-500">{p.time} · {p.parts}</p></div></button>)}</div></Section><Section title="Africa is building the future" kicker="Africa Tech"><div className="grid gap-6 lg:grid-cols-2"><div className="glass-card grid min-h-80 place-items-center grid-bg"><Globe2 size={220} strokeWidth={.35} className="text-orange"/></div><div className="glass-card p-7"><div className="font-mono text-[10px] text-orange">AFRICA / RWANDA</div><h3 className="mt-4 font-display text-3xl font-bold">Rwanda to Africa, Africa to the world.</h3><p className="mt-4 leading-8 text-zinc-400">Track startups, research, robotics, AI, electronics, infrastructure and technology initiatives across the continent.</p><LiquidButton ghost onClick={()=>go("africa")}>Explore Africa Tech <ArrowRight className="ml-1 inline" size={14}/></LiquidButton></div></div></Section></>};
function News(){return <Page title="Technology news" kicker="Live newsroom"><LiveTrending/></Page>}
function Article({id,saved,toggle}:{id:string;saved:Set<string>;toggle:(x:string)=>void}){const[data,setData]=useState<any>(null);const[loading,setLoading]=useState(true);useEffect(()=>{api.article(id).then(setData).catch(()=>setData(null)).finally(()=>setLoading(false))},[id]);if(loading)return <Page title="Loading story" kicker="NextBit editorial"><div className="glass-card mx-auto max-w-5xl h-96 animate-pulse"/></Page>;if(data)return <article className="mx-auto max-w-5xl px-5 pb-24 pt-32"><div className="font-mono text-[10px] uppercase tracking-[.2em] text-orange">{data.category} · {data.published_at?new Date(data.published_at).toLocaleDateString():"NextBit"}</div><h1 className="mt-4 font-display text-5xl font-bold leading-tight md:text-7xl">{data.title}</h1><p className="mt-6 text-xl leading-8 text-zinc-400">{data.summary}</p><div className="mt-6 flex flex-wrap items-center gap-4 text-xs text-zinc-500"><span>By {data.author||"NextBit Desk"}</span>{data.verified&&<span className="text-orange">✓ Verified source</span>}<button onClick={()=>toggle(data.id)} className="ml-auto border border-line px-3 py-2">{saved.has(data.id)?"Saved":"Save article"} <Bookmark className="ml-1 inline" size={14}/></button></div>{data.image_url&&<img src={data.image_url} className="mt-10 aspect-[16/8] w-full object-cover" alt=""/>}<div className="mt-12 grid gap-10 md:grid-cols-[1fr_250px]"><div className="prose prose-invert max-w-none text-zinc-300">{String(data.body||"").split(/\n\s*\n/).map((p:string,i:number)=><p key={i} className="text-lg leading-8">{p}</p>)}{data.source_url&&<div className="my-10 border border-orange/30 bg-orange/5 p-6"><div className="font-mono text-[10px] text-orange">ORIGINAL SOURCE</div><p className="mt-2 text-sm text-zinc-400">This story may include NextBit editorial analysis. Visit the original source for primary reporting.</p><a href={data.source_url} target="_blank" rel="noreferrer" className="mt-4 inline-flex text-orange">Read original source ↗</a></div>}</div><aside className="glass-card h-fit p-5"><div className="font-mono text-[10px] text-orange">NEXTBIT DESK</div><p className="mt-2 text-sm text-zinc-300">Original editorial published by the NextBit team.</p><p className="mt-4 text-xs text-zinc-600">Published {data.published_at?new Date(data.published_at).toLocaleString():"—"}</p></aside></div></article>;const fallback=A.find(x=>x.id===id)||A[0];return <article className="mx-auto max-w-5xl px-5 pb-24 pt-32"><div className="font-mono text-[10px] uppercase tracking-[.2em] text-orange">{fallback.cat}</div><h1 className="mt-4 font-display text-5xl font-bold leading-tight md:text-7xl">{fallback.title}</h1><p className="mt-6 text-xl leading-8 text-zinc-400">{fallback.sub}</p><img src={fallback.img} className="mt-10 aspect-[16/8] w-full object-cover" alt=""/><div className="mt-12 text-zinc-400"><p className="text-lg leading-8">NextBit editorial content will appear here once the article is available.</p></div></article>}
function Roadmaps(){const[group,setGroup]=useState("All");const groups=["All",...Array.from(new Set(ROADMAPS.map(x=>x.group)))];const items=ROADMAPS.filter(x=>group==="All"||x.group===group);return <Page title="ICT Roadmaps" kicker="Global technology map"><p className="mb-8 max-w-3xl text-lg leading-8 text-zinc-400">A worldwide map of major ICT disciplines—from software and AI to cybersecurity, telecom, electronics, semiconductors, space, quantum and applied technology.</p><div className="mb-8 flex flex-wrap gap-2">{groups.map(x=><button key={x} onClick={()=>setGroup(x)} className={group===x?"bg-orange px-4 py-2 text-xs text-black":"border border-line px-4 py-2 text-xs text-zinc-400"}>{x}</button>)}</div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{items.map(r=><button key={r.id} onClick={()=>go("roadmap",r.id)} className="group border border-line bg-card p-6 text-left hover:border-orange/50"><div className="font-mono text-[9px] uppercase tracking-[.2em] text-orange">{r.group}</div><h3 className="mt-3 font-display text-2xl font-semibold group-hover:text-orange">{r.title}</h3><p className="mt-3 text-sm leading-6 text-zinc-500">{r.desc}</p><div className="mt-6 flex items-center text-xs text-zinc-500">{r.steps.length} stages <ArrowRight className="ml-auto text-orange" size={15}/></div></button>)}</div></Page>}
function Roadmap({id}:{id:string}){const r=ROADMAPS.find(x=>x.id===id)||ROADMAPS[0];return <Page title={r.title} kicker={"Roadmap · "+r.group}><p className="max-w-3xl text-lg leading-8 text-zinc-400">{r.desc}</p><div className="mt-10 grid gap-3">{r.steps.map((s,i)=><div key={s} className="grid gap-4 border border-line bg-card p-5 md:grid-cols-[70px_1fr_auto] md:items-center"><div className="font-mono text-sm text-orange">{String(i+1).padStart(2,"0")}</div><div><h3 className="font-display text-xl font-semibold">{s}</h3><p className="mt-1 text-xs text-zinc-500">Core stage in the {r.title.toLowerCase()} roadmap.</p></div><span className="text-xs text-zinc-600">Stage {i+1}</span></div>)}</div><div className="mt-8 grid gap-4 md:grid-cols-3"><div className="border border-line bg-card p-5"><div className="font-mono text-[10px] text-orange">USE THIS ROADMAP</div><p className="mt-3 text-sm text-zinc-400">Track the technologies, roles and ecosystems that matter in this discipline.</p></div><div className="border border-line bg-card p-5"><div className="font-mono text-[10px] text-orange">NEXTBIT CONNECTION</div><p className="mt-3 text-sm text-zinc-400">Connect roadmap stages to relevant news and projects as the platform grows.</p></div><div className="border border-line bg-card p-5"><div className="font-mono text-[10px] text-orange">GLOBAL SCOPE</div><p className="mt-3 text-sm text-zinc-400">Covers industry, research, infrastructure and emerging ICT paths worldwide.</p></div></div></Page>}function Build(){return <Page title="Build something" kicker="Hardware + software"><div className="grid gap-5 md:grid-cols-3">{P.map(p=><button onClick={()=>go("project",p.id)} className="overflow-hidden border border-line bg-card text-left" key={p.id}><img src={p.img} className="h-48 w-full object-cover" alt=""/><div className="p-5"><span className="font-mono text-[10px] text-orange">{p.tech} · {p.level}</span><h3 className="mt-2 font-display text-xl font-semibold">{p.title}</h3><p className="mt-3 text-sm text-zinc-500">{p.parts}</p></div></button>)}</div></Page>}
function Project({id}:{id:string}){const p=P.find(x=>x.id===id)||P[0];return <Page title={p.title} kicker={"Project · "+p.tech}><div className="grid gap-7 lg:grid-cols-2"><img src={p.img} className="h-[420px] w-full object-cover" alt=""/><div className="border border-line bg-card p-7"><div className="grid grid-cols-3 gap-2 text-center text-xs"><span className="border border-line p-3">{p.level}</span><span className="border border-line p-3">{p.time}</span><span className="border border-line p-3">DIY</span></div><h2 className="mt-7 font-display text-3xl font-bold">Build overview</h2><p className="mt-4 leading-7 text-zinc-400">Prerequisites, components, wiring, source code, steps, testing and completion tracking belong here.</p><div className="mt-6 border border-line p-4"><span className="font-mono text-[10px] text-orange">REQUIRED PARTS</span><p className="mt-2 text-sm">{p.parts}</p></div><button className="mt-6 w-full bg-orange px-5 py-3 font-semibold text-black">Start project</button></div></div></Page>}
function Simple({title,children}:{title:string;children:React.ReactNode}){return <Page title={title}><div className="mx-auto max-w-3xl border border-line bg-card p-8 leading-8 text-zinc-400">{children}</div></Page>}
function AuthPage({mode}:{mode:"login"|"register"}){const[form,setForm]=useState({name:"",email:"",password:""});const[msg,setMsg]=useState("");const[busy,setBusy]=useState(false);const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMsg("");try{const out=mode==="login"?await api.login({email:form.email,password:form.password}):await api.register(form);localStorage.setItem("nextbit_token",out.token);setMsg("Success. Your session is ready.");setTimeout(()=>go("profile"),300)}catch(err){setMsg(err instanceof Error?err.message:"Unable to complete request")}finally{setBusy(false)}};return <Page title={mode==="login"?"Welcome back":"Create your NextBit account"} kicker={mode==="login"?"Account":"Join NextBit"}><form onSubmit={submit} className="glass-card mx-auto max-w-lg p-7">{mode==="register"&&<input required minLength={2} value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="mb-3 w-full border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Full name"/>}<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="mb-3 w-full border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Email address"/><input required minLength={8} type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} className="mb-5 w-full border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Password (8+ characters)"/><button disabled={busy} className="liquid-button w-full disabled:opacity-50">{busy?"Connecting…":mode==="login"?"Sign in":"Create account"} <ArrowRight className="ml-2 inline" size={15}/></button>{msg&&<p className="mt-4 text-sm text-zinc-400">{msg}</p>}</form></Page>}
function NewsletterPage(){const[email,setEmail]=useState("");const[msg,setMsg]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await api.subscribe(email);setMsg("You’re subscribed to The NextBit Brief.");setEmail("")}catch(err){setMsg(err instanceof Error?err.message:"Subscription failed")}};return <Page title="The NextBit Brief" kicker="Newsletter"><div className="glass-card mx-auto max-w-2xl p-8"><p className="text-lg leading-8 text-zinc-400">One strong digest of technology signals, platform shifts, major launches and Africa tech.</p><form onSubmit={submit} className="mt-7 flex flex-col gap-3 sm:flex-row"><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} className="flex-1 border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="you@example.com"/><button className="liquid-button">Subscribe <ArrowRight className="ml-1 inline" size={15}/></button></form>{msg&&<p className="mt-4 text-sm text-zinc-400">{msg}</p>}</div></Page>}
function ContactPage(){const[form,setForm]=useState({name:"",email:"",message:""});const[msg,setMsg]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await api.contact(form);setMsg("Message received.");setForm({name:"",email:"",message:""})}catch(err){setMsg(err instanceof Error?err.message:"Message failed")}};return <Page title="Contact" kicker="Editorial / partnerships"><form onSubmit={submit} className="glass-card mx-auto max-w-2xl p-7"><div className="grid gap-3 sm:grid-cols-2"><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Name"/><input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Email"/></div><textarea required minLength={5} value={form.message} onChange={e=>setForm({...form,message:e.target.value})} className="mt-3 min-h-44 w-full border border-line bg-black/30 px-4 py-3 outline-none focus:border-orange/50" placeholder="Message"/><button className="liquid-button mt-4">Send message <ArrowRight className="ml-1 inline" size={15}/></button>{msg&&<p className="mt-4 text-sm text-zinc-400">{msg}</p>}</form></Page>}

function Admin(){type ArticleForm={slug:string;category:string;title:string;summary:string;body:string;image_url:string;source_url:string;author:string;status:"draft"|"review"|"fact_check"|"verified"|"published"|"archived";verified:boolean};const blank:ArticleForm={slug:"",category:"AI",title:"",summary:"",body:"",image_url:"",source_url:"",author:"NextBit Desk",status:"draft",verified:false};const[token]=useState(localStorage.getItem("nextbit_token")||"");const[user,setUser]=useState<any>(null);const[tab,setTab]=useState<"overview"|"articles"|"users"|"inbox"|"sources"|"activity"|"editor">("overview");const[overview,setOverview]=useState<any>(null);const[articles,setArticles]=useState<any[]>([]);const[users,setUsers]=useState<any[]>([]);const[contacts,setContacts]=useState<any[]>([]);const[sources,setSources]=useState<any[]>([]);const[activity,setActivity]=useState<any[]>([]);const[editing,setEditing]=useState<any>(null);const[form,setForm]=useState<ArticleForm>(blank);const[sourceForm,setSourceForm]=useState({name:"",url:"",reliability:"unverified",verification_notes:""});const[search,setSearch]=useState("");const[msg,setMsg]=useState("");const[busy,setBusy]=useState(false);const[health,setHealth]=useState<any>(null);const load=async()=>{if(!token){setMsg("Sign in with the configured admin account first.");return}setBusy(true);try{const me=await api.me(token);setUser(me);if(me.role!=="admin"){setMsg("This account does not have admin access.");return}const[o,aa,uu,cc,ss,act,h]=await Promise.all([api.adminOverview(token),api.adminArticles(token),api.adminUsers(token),api.adminContacts(token),api.adminSources(token),api.adminActivity(token),api.health()]);setOverview(o);setArticles(aa);setUsers(uu);setContacts(cc);setSources(ss);setActivity(act);setHealth(h)}catch(e){setMsg(e instanceof Error?e.message:"Unable to load admin data")}finally{setBusy(false)}};useEffect(()=>{load()},[]);const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{if(editing)await api.updateArticle(token,editing.id,form);else await api.createArticle(token,form);setMsg(editing?"Article updated successfully":"Article created successfully");setForm(blank);setEditing(null);setTab("articles");await load()}catch(e){setMsg(e instanceof Error?e.message:"Save failed")}finally{setBusy(false)}};const remove=async(id:string)=>{if(!confirm("Delete this article permanently?"))return;setBusy(true);try{await api.deleteArticle(token,id);setMsg("Article deleted.");await load()}catch(e){setMsg(e instanceof Error?e.message:"Delete failed")}finally{setBusy(false)}};const editUser=async(id:string,key:"role"|"status",value:string)=>{try{await api.updateUser(token,id,{[key]:value});setUsers(await api.adminUsers(token));setMsg("User updated.")}catch(e){setMsg(e instanceof Error?e.message:"User update failed")}};const updateContact=async(id:string,status:string)=>{try{await api.updateContact(token,id,status);setContacts(await api.adminContacts(token));setMsg("Inbox status updated.")}catch(e){setMsg(e instanceof Error?e.message:"Inbox update failed")}};const addSource=async(e:React.FormEvent)=>{e.preventDefault();try{await api.createSource(token,sourceForm);setSourceForm({name:"",url:"",reliability:"unverified",verification_notes:""});setSources(await api.adminSources(token));setMsg("Source added.")}catch(e){setMsg(e instanceof Error?e.message:"Source creation failed")}};const refreshFeeds=async()=>{try{setBusy(true);const d=await api.refreshTrending(token);setMsg(`Live news refreshed: ${d.items?.length||0} stories received.`)}catch(e){setMsg(e instanceof Error?e.message:"Feed refresh failed")}finally{setBusy(false)}};const filtered=articles.filter(a=>(a.title+" "+a.category+" "+a.status).toLowerCase().includes(search.toLowerCase()));if(!token||!user)return <Page title="Admin access" kicker="Protected console"><div className="glass-card mx-auto max-w-xl p-8"><div className="font-mono text-[10px] text-orange">NEXTBIT CONTROL PLANE</div><h2 className="mt-3 font-display text-3xl font-bold">Administrator authentication required.</h2><p className="mt-3 text-zinc-400">Use the account whose email is configured as ADMIN_EMAIL in Render.</p><LiquidButton onClick={()=>go("login")}>Sign in to admin <ArrowRight className="ml-1 inline" size={14}/></LiquidButton></div></Page>;if(user.role!=="admin")return <Page title="Access denied" kicker="Admin CMS"><div className="glass-card mx-auto max-w-xl p-8 text-zinc-400">Your account is authenticated but does not have the administrator role.</div></Page>;const tabs=[["overview","Overview"],["articles","Content"],["users","Users"],["inbox","Inbox"],["sources","Sources"],["activity","Audit log"],["editor","Compose"]];return <main className="min-h-screen bg-ink pt-24"><div className="mx-auto max-w-[1600px] px-4 pb-20 lg:px-8"><div className="grid gap-5 lg:grid-cols-[230px_1fr]"><aside className="glass-card h-fit p-4 lg:sticky lg:top-24"><div className="mb-5 border-b border-line pb-5"><div className="font-mono text-[9px] uppercase tracking-[.25em] text-orange">NEXTBIT / CONTROL</div><div className="mt-2 font-display text-xl font-bold">{user.name}</div><div className="mt-1 text-xs text-zinc-600">{user.email}</div><div className="mt-3 inline-flex border border-orange/20 bg-orange/5 px-2 py-1 font-mono text-[9px] text-orange">ADMIN</div></div><div className="grid gap-1">{tabs.map(([id,label])=><button key={id} onClick={()=>{setTab(id as any);if(id==="editor"){setEditing(null);setForm(blank)}}} className={tab===id?"rounded-xl bg-orange px-4 py-3 text-left text-sm font-semibold text-black":"rounded-xl px-4 py-3 text-left text-sm text-zinc-400 hover:bg-white/5 hover:text-white"}>{label}<span className="float-right text-[10px] opacity-60">{id==="articles"?articles.length:id==="users"?users.length:id==="inbox"?contacts.length:id==="sources"?sources.length:""}</span></button>)}</div><button onClick={refreshFeeds} className="mt-2 w-full rounded-xl border border-orange/20 bg-orange/5 px-4 py-3 text-left text-sm text-orange hover:bg-orange/10">Refresh live news</button><button onClick={()=>{localStorage.removeItem("nextbit_token");go("login")}} className="mt-2 w-full rounded-xl border border-line px-4 py-3 text-left text-sm text-zinc-500 hover:text-white">Sign out</button></aside><section className="min-w-0"><div className="mb-5 flex flex-col gap-4 rounded-2xl border border-line bg-white/[.03] p-5 backdrop-blur-xl xl:flex-row xl:items-center xl:justify-between"><div><div className="font-mono text-[9px] uppercase tracking-[.25em] text-orange">OPERATIONS / {tab}</div><h1 className="mt-2 font-display text-3xl font-bold">Editorial command center</h1><p className="mt-1 text-sm text-zinc-500">Control content, users, sources and platform operations from one workspace.</p></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full border border-line bg-black/20 px-3 py-2 text-xs text-zinc-400"><span className={health?.database==="ok"?"mr-2 inline-block size-2 rounded-full bg-emerald-400":"mr-2 inline-block size-2 rounded-full bg-red-400"}/>DB {health?.database||"checking"}</span><span className="rounded-full border border-line bg-black/20 px-3 py-2 text-xs text-zinc-400">{busy?"Syncing…":"Live"}</span></div></div>{msg&&<div className="mb-5 rounded-2xl border border-orange/30 bg-orange/5 p-4 text-sm text-zinc-300">{msg}</div>}

{tab==="overview"&&<div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{[["Articles",overview?.articles?.count??"—"],["Published",overview?.articles?.published??"—"],["Drafts",overview?.articles?.drafts??"—"],["Users",overview?.users??"—"],["Subscribers",overview?.subscribers??"—"]].map(([n,v])=><div key={n} className="glass-card p-5"><div className="font-mono text-[9px] uppercase tracking-[.2em] text-orange">{n}</div><div className="mt-3 font-display text-4xl font-bold">{v}</div><div className="mt-2 text-[11px] text-zinc-600">Realtime database metric</div></div>)}</div><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><div className="glass-card p-6"><div className="flex items-center justify-between"><div><div className="font-mono text-[9px] text-orange">CONTENT PIPELINE</div><h2 className="mt-2 font-display text-2xl font-bold">Editorial queue</h2></div><button onClick={()=>setTab("articles")} className="text-sm text-orange">Open content →</button></div><div className="mt-5 grid gap-2 md:grid-cols-5">{["draft","review","fact_check","verified","published"].map((x,i)=><div key={x} className="rounded-xl border border-line bg-black/20 p-4"><div className="font-mono text-[9px] text-orange">0{i+1}</div><div className="mt-5 text-xs text-zinc-400">{x.replace("_"," ")}</div></div>)}</div></div><div className="glass-card p-6"><div className="font-mono text-[9px] text-orange">SYSTEM</div><div className="mt-5 space-y-3 text-sm text-zinc-400"><div className="flex justify-between"><span>API</span><span className="text-emerald-400">Operational</span></div><div className="flex justify-between"><span>Database</span><span className={health?.database==="ok"?"text-emerald-400":"text-red-400"}>{health?.database||"Checking"}</span></div><div className="flex justify-between"><span>New contacts</span><span>{overview?.newContacts??"—"}</span></div><div className="flex justify-between"><span>Events</span><span>{overview?.events??"—"}</span></div></div></div></div></div>}

{tab==="articles"&&<div className="glass-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-line p-5 md:flex-row md:items-center md:justify-between"><div><div className="font-display text-xl font-bold">Content library</div><div className="text-xs text-zinc-600">{filtered.length} matching articles</div></div><div className="flex gap-2"><input value={search} onChange={e=>setSearch(e.target.value)} className="w-full border border-line bg-black/30 px-3 py-2 text-sm outline-none md:w-72" placeholder="Search content…"/><LiquidButton onClick={()=>{setEditing(null);setForm(blank);setTab("editor")}}>New</LiquidButton></div></div><div className="overflow-x-auto"><table className="w-full min-w-[1000px] text-left text-sm"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.15em] text-zinc-600"><th className="p-4">Article</th><th>Category</th><th>Status</th><th>Source</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{filtered.map(a=><tr key={a.id} className="border-b border-line/60 hover:bg-white/[.02]"><td className="p-4"><div className="font-semibold">{a.title}</div><div className="mt-1 max-w-md text-xs text-zinc-600">{a.summary}</div></td><td className="text-xs text-zinc-400">{a.category}</td><td><span className="rounded-full border border-line px-2 py-1 text-[9px] uppercase">{a.status}</span></td><td className="text-xs">{a.verified?<span className="text-emerald-400">Verified</span>:<span className="text-amber-400">Review</span>}</td><td className="text-xs text-zinc-600">{a.created_at?new Date(a.created_at).toLocaleDateString():"—"}</td><td><button className="mr-3 text-orange" onClick={()=>{setEditing(a);setForm({...blank,...a});setTab("editor")}}>Edit</button><button className="text-red-400" onClick={()=>remove(a.id)}>Delete</button></td></tr>)}</tbody></table></div></div>}

{tab==="users"&&<div className="glass-card overflow-hidden"><div className="border-b border-line p-5"><div className="font-display text-xl font-bold">User control</div><p className="mt-1 text-xs text-zinc-600">Manage roles and account access.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.15em] text-zinc-600"><th className="p-4">User</th><th>Role</th><th>Status</th><th>Last login</th><th>Created</th></tr></thead><tbody>{users.map(u=><tr key={u.id} className="border-b border-line/60"><td className="p-4"><div className="font-semibold">{u.name}</div><div className="text-xs text-zinc-600">{u.email}</div></td><td><select value={u.role} onChange={e=>editUser(u.id,"role",e.target.value)} className="border border-line bg-black/40 p-2 text-xs"><option value="user">User</option><option value="editor">Editor</option><option value="admin">Admin</option></select></td><td><select value={u.status} onChange={e=>editUser(u.id,"status",e.target.value)} className="border border-line bg-black/40 p-2 text-xs"><option value="active">Active</option><option value="suspended">Suspended</option></select></td><td className="text-xs text-zinc-600">{u.last_login_at?new Date(u.last_login_at).toLocaleString():"Never"}</td><td className="text-xs text-zinc-600">{u.created_at?new Date(u.created_at).toLocaleDateString():"—"}</td></tr>)}</tbody></table></div></div>}

{tab==="inbox"&&<div className="glass-card overflow-hidden"><div className="border-b border-line p-5"><div className="font-display text-xl font-bold">Editorial inbox</div><p className="mt-1 text-xs text-zinc-600">Corrections, partnerships and incoming messages.</p></div><div className="grid gap-3 p-5">{contacts.map(x=><div key={x.id} className="rounded-xl border border-line bg-black/20 p-5"><div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><div className="font-semibold">{x.name} <span className="text-zinc-600">· {x.email}</span></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-zinc-400">{x.message}</p></div><select value={x.status} onChange={e=>updateContact(x.id,e.target.value)} className="border border-line bg-black/40 p-2 text-xs"><option value="new">New</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="spam">Spam</option></select></div></div>)}</div></div>}

{tab==="sources"&&<div className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]"><form onSubmit={addSource} className="glass-card p-6"><div className="font-mono text-[9px] text-orange">SOURCE REGISTRY</div><h2 className="mt-2 font-display text-2xl font-bold">Add a source</h2><input required value={sourceForm.name} onChange={e=>setSourceForm({...sourceForm,name:e.target.value})} className="mt-5 w-full border border-line bg-black/30 p-3 outline-none" placeholder="Publisher / source name"/><input required type="url" value={sourceForm.url} onChange={e=>setSourceForm({...sourceForm,url:e.target.value})} className="mt-3 w-full border border-line bg-black/30 p-3 outline-none" placeholder="https://example.com"/><select value={sourceForm.reliability} onChange={e=>setSourceForm({...sourceForm,reliability:e.target.value})} className="mt-3 w-full border border-line bg-black/30 p-3 outline-none"><option value="trusted">Trusted</option><option value="review">Review</option><option value="unverified">Unverified</option></select><textarea value={sourceForm.verification_notes} onChange={e=>setSourceForm({...sourceForm,verification_notes:e.target.value})} className="mt-3 min-h-28 w-full border border-line bg-black/30 p-3 outline-none" placeholder="Verification notes"/><LiquidButton>Register source</LiquidButton></form><div className="glass-card overflow-hidden"><div className="border-b border-line p-5"><div className="font-display text-xl font-bold">Verified sources</div></div><div className="divide-y divide-white/5">{sources.map(s=><div key={s.id} className="p-5"><div className="flex items-center justify-between gap-3"><div><div className="font-semibold">{s.name}</div><div className="text-xs text-zinc-600">{s.url}</div></div><span className={s.reliability==="trusted"?"text-emerald-400":s.reliability==="review"?"text-amber-400":"text-zinc-500"}>{s.reliability}</span></div>{s.verification_notes&&<p className="mt-2 text-xs leading-5 text-zinc-500">{s.verification_notes}</p>}</div>)}</div></div></div>}

{tab==="activity"&&<div className="glass-card overflow-hidden"><div className="border-b border-line p-5"><div className="font-display text-xl font-bold">Audit trail</div><p className="mt-1 text-xs text-zinc-600">Administrative operations recorded by the backend.</p></div><div className="divide-y divide-white/5">{activity.map(x=><div key={x.id} className="flex flex-col gap-1 p-5 md:flex-row md:items-center md:justify-between"><div><span className="font-mono text-[10px] text-orange">{x.action}</span><div className="mt-1 text-sm text-zinc-300">{x.target_type||"system"} / {x.target_id||"—"}</div></div><div className="text-right text-xs text-zinc-600">{x.admin_name||"admin"} · {x.created_at?new Date(x.created_at).toLocaleString():"—"}</div></div>)}</div></div>}

{tab==="editor"&&<form onSubmit={save} className="grid gap-6 lg:grid-cols-[1fr_340px]"><div className="glass-card p-7"><div className="mb-5 flex items-center justify-between"><div><div className="font-mono text-[9px] text-orange">EDITORIAL STUDIO</div><div className="mt-1 font-display text-2xl font-bold">{editing?"Edit article":"Compose story"}</div></div><span className="rounded-full border border-line px-3 py-2 text-[10px] text-zinc-500">Autosave-ready UI</span></div><input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className="w-full border-b border-line bg-transparent py-5 font-display text-4xl font-bold outline-none" placeholder="Headline"/><div className="mt-4 grid gap-3 sm:grid-cols-2"><input required value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})} className="border border-line bg-black/30 p-3 outline-none" placeholder="slug"/><input required value={form.category} onChange={e=>setForm({...form,category:e.target.value})} className="border border-line bg-black/30 p-3 outline-none" placeholder="category"/></div><textarea required value={form.summary} onChange={e=>setForm({...form,summary:e.target.value})} className="mt-3 min-h-28 w-full border border-line bg-black/30 p-4 outline-none" placeholder="Summary / dek"/><textarea value={form.body} onChange={e=>setForm({...form,body:e.target.value})} className="mt-3 min-h-[420px] w-full border border-line bg-black/30 p-4 leading-7 outline-none" placeholder="Write the full technology story…"/><div className="mt-3 grid gap-3 sm:grid-cols-2"><input value={form.image_url} onChange={e=>setForm({...form,image_url:e.target.value})} className="border border-line bg-black/30 p-3 outline-none" placeholder="Image URL"/><input value={form.source_url} onChange={e=>setForm({...form,source_url:e.target.value})} className="border border-line bg-black/30 p-3 outline-none" placeholder="Source URL"/></div></div><aside className="glass-card h-fit p-6 lg:sticky lg:top-24"><div className="font-mono text-[9px] text-orange">PUBLISHING</div><label className="mt-5 block text-xs text-zinc-500">Author<input value={form.author} onChange={e=>setForm({...form,author:e.target.value})} className="mt-2 w-full border border-line bg-black/30 p-3 outline-none"/></label><label className="mt-4 block text-xs text-zinc-500">Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value as ArticleForm["status"]})} className="mt-2 w-full border border-line bg-black/30 p-3 outline-none"><option value="draft">Draft</option><option value="review">Review</option><option value="fact_check">Fact check</option><option value="verified">Verified</option><option value="published">Published</option><option value="archived">Archived</option></select></label><label className="mt-4 flex items-center gap-2 text-sm"><input type="checkbox" checked={form.verified} onChange={e=>setForm({...form,verified:e.target.checked})}/> Verified source</label><LiquidButton>{editing?"Update article":"Publish / save"}</LiquidButton><button type="button" onClick={()=>setTab("articles")} className="liquid-button ghost mt-2 w-full">Cancel</button></aside></form>}</section></div></div></main>}
function Editor(){return <Page title="Article editor" kicker="Draft → verify → publish"><div className="grid gap-6 lg:grid-cols-[1fr_320px]"><div className="border border-line bg-card p-7"><input className="w-full border-b border-line bg-transparent py-4 font-display text-3xl font-bold outline-none" placeholder="Article headline..."/><textarea className="mt-7 min-h-64 w-full border border-line bg-ink p-5 leading-7 outline-none" placeholder="Write the article body..."/></div><aside className="border border-line bg-card p-6"><div className="font-mono text-[10px] text-orange">PUBLISHING</div>{["Draft","In review","Fact check","Verified","Published"].map(x=><button key={x} className="mt-3 flex w-full items-center border border-line p-3 text-left text-sm"><span className="mr-3 size-2 rounded-full bg-orange"/>{x}<Check className="ml-auto text-zinc-700" size={14}/></button>)}<button className="mt-6 w-full bg-orange py-3 font-semibold text-black">Save draft</button></aside></div></Page>}
function SearchPage(){const[q,setQ]=useState("");return <Page title="Search technology" kicker="Discovery"><div className="flex border border-line bg-card"><Search className="m-4 text-zinc-600"/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Search technology, ideas, projects..." className="w-full bg-transparent py-4 outline-none"/></div><div className="mt-6 grid gap-4">{A.filter(a=>(a.title+a.sub+a.cat).toLowerCase().includes(q.toLowerCase())).map(a=><Card a={a} key={a.id} saved={false} toggle={()=>{}}/>)}</div></Page>}
function App(){const{r,id}=useRoute();const[saved,setSaved]=useState(new Set(["a2"]));const toggle=(x:string)=>setSaved(s=>{const n=new Set(s);n.has(x)?n.delete(x):n.add(x);return n});let c:React.ReactNode;switch(r){case"home":c=<><Hero/><Ticker/><Home saved={saved} toggle={toggle}/></>;break;case"news":c=<News/>;break;case"article":c=<Article id={id} saved={saved} toggle={toggle}/>;break;case"roadmaps":c=<Roadmaps/>;break;case"roadmap":c=<Roadmap id={id}/>;break;case"build":c=<Build/>;break;case"project":c=<Project id={id}/>;break;case"africa":c=<Page title="Africa is building the future" kicker="Africa Tech"><div className="grid gap-6 lg:grid-cols-2"><div className="grid-bg flex min-h-96 items-center justify-center border border-line bg-card"><Globe2 size={280} strokeWidth={.3} className="text-orange"/></div><Simple title="Rwanda Tech">Startups, research, universities, robotics, AI, electronics and ICT initiatives across Rwanda and Africa.</Simple></div></Page>;break;case"profile":c=<Simple title="Your NextBit">Followed topics, saved stories, roadmap tracking, projects and technology interests.</Simple>;break;case"bookmarks":c=<Simple title="Saved technology">You have {saved.size} saved stories.</Simple>;break;case"notifications":c=<Simple title="Notifications">Live updates, roadmap alerts, followed-topic alerts and editorial announcements are ready for backend connection.</Simple>;break;case"search":c=<SearchPage/>;break;case"admin":c=<Admin/>;break;case"editor":c=<Editor/>;break;case"sources":c=<Simple title="Source management">Manage source name, URL, author, publication date, retrieval date, reliability and verification state.</Simple>;break;case"users":c=<Simple title="User management">Manage roles, profile status, moderation flags and account access.</Simple>;break;case"moderation":c=<Simple title="Moderation">Review comments, reports and editorial flags. Do not auto-publish unverified content.</Simple>;break;case"analytics":c=<Simple title="Analytics">Track page views, article views, unique visitors, searches, bookmarks, comments, roadmap tracking and newsletter growth.</Simple>;break;case"newsletter":c=<NewsletterPage/>;break;case"about":c=<Simple title="About NextBit">NextBit Updates is a global ICT news and roadmap platform focused on software, hardware, infrastructure, cybersecurity and African innovation.</Simple>;break;case"contact":c=<ContactPage/>;break;case"privacy":c=<Simple title="Privacy">Collect only the data required for accounts, saved content, roadmap tracking, moderation and analytics. Review legal text before launch.</Simple>;break;case"terms":c=<Simple title="Terms">Define clear rules for accounts, content, comments, intellectual property, source attribution and responsible use.</Simple>;break;case"settings":c=<Simple title="Settings">Account, notifications, privacy, accessibility and appearance preferences belong here.</Simple>;break;case"login":c=<AuthPage mode="login"/>;break;case"register":c=<AuthPage mode="register"/>;break;default:c=<Simple title="Bit not found">The requested page does not exist.</Simple>}return <><Nav saved={saved.size}/>{c}<Footer/></>};export default App;